if (!Number.isSafeInteger(timestampSeconds) || Math.abs(Math.floor(Date.now() / 1000) - timestampSeconds) > 300) return reject();
const expected = Buffer.from(`sha256=${crypto.createHmac('sha256', secret).update(`${timestamp}.${rawBody}`).digest('hex')}`, 'utf8');
const supplied = Buffer.from(signature, 'utf8');
if (expected.length !== supplied.length || !crypto.timingSafeEqual(expected, supplied)) return reject();
let event;
try {
  event = JSON.parse(rawBody);
} catch {
  return reject();
}
if (!event || typeof event !== 'object' || Array.isArray(event)) return reject();
const uuid = /^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i;
const validReceivedAt = event.received_at === null || (typeof event.received_at === 'string' && /^[0-9]{4}-[0-9]{2}-[0-9]{2}T[0-9]{2}:[0-9]{2}:[0-9]{2}([.][0-9]+)?Z$/.test(event.received_at) && !Number.isNaN(Date.parse(event.received_at)));
if (event.event_type !== 'whatsapp.inbound' || typeof event.event_id !== 'string' || !uuid.test(event.event_id) || typeof event.provider_message_id !== 'string' || event.provider_message_id.length < 1 || event.provider_message_id.length > 200 || typeof event.tenant_id !== 'string' || event.tenant_id.length < 1 || event.tenant_id.length > 128 || typeof event.org_ref !== 'string' || event.org_ref.length < 1 || event.org_ref.length > 160 || typeof event.conversation_id !== 'string' || !uuid.test(event.conversation_id) || typeof event.recipient_hash !== 'string' || !/^[0-9a-f]{64}$/.test(event.recipient_hash) || !validReceivedAt || typeof event.body !== 'string' || event.body.length > 4096) return reject();
