const crypto = require('crypto');
const input = $input.first().json;
const secret = process.env.N8N_WHATSAPP_SIGNING_SECRET;
if (typeof secret !== 'string' || secret.length < 32 || typeof input.reply_body !== 'string' || input.reply_body.length < 1 || input.reply_body.length > 4096) throw new Error('Reply signing is not configured');
